2157	// Build the docked reply panel's prompt body as a default-collapsed,
2158	// expand-on-demand container. Returns a wrapper holding a "展开/收起消息详情"
2159	// trigger button plus a `.flow-reply-prompt` body (Markdown rendered, never
2160	// truncated) that starts hidden. Clicking the trigger toggles the body and,
2161	// on expand only, scrolls it into view (requestAnimationFrame-wrapped, matching
2162	// the foldable behavior elsewhere in this view); collapsing does not scroll.
2163	// The body stays mounted while hidden so the existing reply-box tests (and the
2164	// CSS height cap that only applies in the expanded state) keep working. Kept as
2165	// a small pure function so the DOM-stub tests can assemble it directly. Scope:
2166	// only the #flow-view docked reply box (updateReplyBox) consumes this.
2167	//
2168	// opts — optional second argument (backward-compatible: callers that omit it
2169	//   get the original default-collapsed, no-persist behaviour):
2170	//   opts.expanded  — initial expanded state (default false);
2171	//   opts.onToggle  — callback invoked on every user click with the new
2172	//                    expanded boolean, so the caller can persist the choice.
2173	function buildCollapsiblePrompt(promptText, opts) {
2174	  const initialExpanded = opts && opts.expanded;
2175	  const onToggle = opts && opts.onToggle;
2176	  const wrap = el("div", "flow-reply-prompt-wrap");
2177	  const collapsedLabel = "▸ 展开消息详情";
2178	  const expandedLabel = "▾ 收起消息详情";
2179	  const btn = el("button", "flow-reply-prompt-toggle",
2180	    initialExpanded ? expandedLabel : collapsedLabel);
2181	  btn.type = "button";
2182	  const body = el("div", "flow-reply-prompt" + (initialExpanded ? "" : " hidden"));
2183	  body.appendChild(renderMarkdown(promptText));
2184	  let expanded = !!initialExpanded;
2185	  if (initialExpanded) {
2186	    wrap.classList.add("expanded");
2187	  }
2188	  btn.addEventListener("click", (e) => {
2189	    e.preventDefault();
2190	    expanded = !expanded;
2191	    body.classList.toggle("hidden", !expanded);
2192	    wrap.classList.toggle("expanded", expanded);
2193	    btn.textContent = expanded ? expandedLabel : collapsedLabel;
2194	    if (onToggle) onToggle(expanded);
2195	    if (expanded) {
2196	      requestAnimationFrame(() => body.scrollIntoView({ block: "nearest" }));
2197	    }
2198	  });
2199	  wrap.append(btn, body);
2200	  return wrap;
2201	}
