1	/*
2	 * Docked reply-box prompt collapse tests (Group G1).
3	 *
4	 * Loaded by tests/frontend/test_app_pure.mjs after its shared DOM stub
5	 * (`globalThis.document` / `FakeNode`) is installed. Exposes
6	 * `registerReplyBoxPromptCollapseTests({app, check, findOne, findAll})` so the
7	 * parent harness can drive the same check() reporter and the same `app` module
8	 * export.
9	 *
10	 * Covers the overflow fix for the running-flow console's docked reply box: a
11	 * pending item with a very long prompt (most notably a discovery_confirm whose
12	 * prompt embeds a whole refined task description) must NOT grow the bar without
13	 * limit. The prompt body is therefore default-collapsed behind an expand/
14	 * collapse trigger, and the expanded body carries the `.flow-reply-prompt`
15	 * class that style.css height-caps (30vh) + scrolls.
16	 *
17	 * Coverage:
18	 *   (a) buildCollapsiblePrompt yields a trigger + a default-hidden body
19	 *       (the limited/scrollable `.flow-reply-prompt` class), expands on click,
20	 *       and collapses on a second click; expanding scrolls into view, collapse
21	 *       does not.
22	 *   (b) the full renderInterventions -> updateReplyBox path keeps the prompt
23	 *       body collapsed by default while header / options stay visible, and the
24	 *       trigger toggles the same body.
25	 */
26	import assert from "node:assert/strict";
