28	export function registerReplyBoxPromptCollapseTests(ctx) {
29	  const { app, check, findOne, findAll } = ctx;
30	
31	  // A pathologically long single-line prompt — the shape that used to push the
32	  // textarea / options / Send out of the docked bar.
33	  const LONG_PROMPT =
