39	    const toggle = findOne(wrap, "flow-reply-prompt-toggle");
40	    assert.ok(toggle, "expected an expand/collapse trigger button");
41	    assert.equal(toggle.tagName, "BUTTON");
42	    const body = findOne(wrap, "flow-reply-prompt");
43	    assert.ok(body, "expected the prompt body to be mounted");
44	    // Default collapsed: body hidden, wrapper not yet expanded.
45	    assert.equal(body.classList.contains("hidden"), true,
46	      "prompt body must start hidden (collapsed)");
47	    assert.equal(wrap.classList.contains("expanded"), false);
48	  });
