1	/*
2	 * Docked reply-box prompt collapse tests (Group G1).
3	 *
4	 * Loaded by tests/frontend/test_app_pure.mjs after its shared DOM stub
5	 * (`globalThis.document` / `FakeNode`) is installed. Exposes
6	 * `registerReplyBoxPromptCollapseTests({app, check, findOne, findAll})` so the
7	 * parent harness can drive the same check() reporter and the same `app` module
8	 * export.
9	 *
10	 * Covers the overflow fix for the running-flow console's docked reply box: a
11	 * pending item with a very long prompt (most notably a discovery_confirm whose
12	 * prompt embeds a whole refined task description) must NOT grow the bar without
13	 * limit. The prompt body is therefore default-collapsed behind an expand/
14	 * collapse trigger, and the expanded body carries the `.flow-reply-prompt`
15	 * class that style.css height-caps (30vh) + scrolls.
16	 *
17	 * Coverage:
18	 *   (a) buildCollapsiblePrompt yields a trigger + a default-hidden body
19	 *       (the limited/scrollable `.flow-reply-prompt` class), expands on click,
20	 *       and collapses on a second click; expanding scrolls into view, collapse
21	 *       does not.
22	 *   (b) the full renderInterventions -> updateReplyBox path keeps the prompt
23	 *       body collapsed by default while header / options stay visible, and the
24	 *       trigger toggles the same body.
25	 */
26	import assert from "node:assert/strict";
27	
28	export function registerReplyBoxPromptCollapseTests(ctx) {
29	  const { app, check, findOne, findAll } = ctx;
30	
31	  // A pathologically long single-line prompt — the shape that used to push the
32	  // textarea / options / Send out of the docked bar.
33	  const LONG_PROMPT =
34	    "Proposed task description: " + "x".repeat(4000) + "\n输入 1 确认";
35	
36	  // ---- (a) buildCollapsiblePrompt unit ------------------------------------
37	  check("G1 buildCollapsiblePrompt defaults to a collapsed body behind a trigger", () => {
38	    const wrap = app.buildCollapsiblePrompt(LONG_PROMPT);
39	    const toggle = findOne(wrap, "flow-reply-prompt-toggle");
40	    assert.ok(toggle, "expected an expand/collapse trigger button");
41	    assert.equal(toggle.tagName, "BUTTON");
42	    const body = findOne(wrap, "flow-reply-prompt");
43	    assert.ok(body, "expected the prompt body to be mounted");
44	    // Default collapsed: body hidden, wrapper not yet expanded.
45	    assert.equal(body.classList.contains("hidden"), true,
46	      "prompt body must start hidden (collapsed)");
47	    assert.equal(wrap.classList.contains("expanded"), false);
48	  });
49	
50	  check("G1 buildCollapsiblePrompt expands then collapses on successive clicks", () => {
51	    const wrap = app.buildCollapsiblePrompt(LONG_PROMPT);
52	    const toggle = findOne(wrap, "flow-reply-prompt-toggle");
53	    const body = findOne(wrap, "flow-reply-prompt");
54	
55	    // Expand.
56	    toggle.dispatch("click");
57	    assert.equal(body.classList.contains("hidden"), false,
58	      "body becomes visible on expand");
59	    assert.equal(wrap.classList.contains("expanded"), true);
60	    // The expanded body keeps the height-capped/scrollable class so the CSS
61	    // 30vh + overflow-y rule bounds it.
62	    assert.equal(body.classList.contains("flow-reply-prompt"), true,
63	      "expanded body keeps the limited/scrollable class");
64	
65	    // Collapse.
66	    toggle.dispatch("click");
67	    assert.equal(body.classList.contains("hidden"), true,
68	      "body hides again on the second click");
69	    assert.equal(wrap.classList.contains("expanded"), false);
70	  });
71	
72	  check("G1 buildCollapsiblePrompt scrolls into view on expand, not on collapse", () => {
73	    const wrap = app.buildCollapsiblePrompt(LONG_PROMPT);
74	    const toggle = findOne(wrap, "flow-reply-prompt-toggle");
75	    const body = findOne(wrap, "flow-reply-prompt");
76	
77	    // Drive requestAnimationFrame synchronously and spy on the body's scroll.
78	    const savedRaf = globalThis.requestAnimationFrame;
